  "hypothesis": "Replacing randomly ordered cut trials with coarse-to-fine refinement around the best cut in each reflection mode will locate a repairable topology change and yield a verified gain of at least 1e-5.",
  "rationale": "The previous search tested isolated cuts and produced only numerical-scale gains, so it may have missed narrow intervals of useful packet rearrangements. This version preserves the topology-search and packet-weight-repair method but allocates the latter part of the search to progressively finer cuts near promising locations, while retaining exact-score acceptance.",
  "source": "import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'search_fraction': (0.43, 0.15, 0.55),
    'total_fraction': (0.70, 0.50, 0.73),
    'repair_tolerance': (0.0003, 0.000001, 0.01, 'log'),
    'beta': (3e8, 1e6, 1e11, 'log'),
    'cuts': (36, 12, 120),
    'coarse_share': (0.55, 0.25, 0.8),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0.0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0.0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.concatenate((a[:k][::-1], a[k:]))
    if mode == 2:
        return np.concatenate((a[:k], a[k:][::-1]))
    return np.concatenate((a[k:], a[:k])) if k else a.copy()


def exact_score(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return float(num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['total_fraction']) * budget_s
    search_end = start + float(params['search_fraction']) * budget_s
    coarse_end = start + float(params['coarse_share']) * (search_end-start)
    if init is None:
        return {'values': [1.0]}
    f0 = decode(init)
    baseline = exact_score(f0)
    n = len(f0)
    if n < 4 or time.monotonic() >= deadline:
        return init
    rng = np.random.default_rng(seed)
    f0 = f0 / float(f0.max())
    m = fft.next_fast_len(2*n-1, real=True)
    best_score = baseline
    best_f = None
    contender = None
    contender_score = -np.inf
    cache = {}
    leaders = [None, None, None]

    def approximate(f):
        s = fft.rfft(f, m)
        c = fft.irfft(s*s, m)[:2*n-1]
        return float((2*np.dot(c, c) + np.dot(c[:-1], c[1:])) /
                     (3*np.sum(np.abs(c))*np.max(np.abs(c))))

    def make(k, mode):
        if mode == 0:
            return np.concatenate((f0[k:], f0[:k]))
        if mode == 1:
            return np.concatenate((f0[:k][::-1], f0[k:]))
        return np.concatenate((f0[:k], f0[k:][::-1]))

    def inspect(k, mode):
        nonlocal best_score, best_f, contender, contender_score
        k = int(k)
        if not 0 < k < n or time.monotonic() >= search_end:
            return None
        key = (k, mode)
        if key in cache:
            return cache[key]
        f = make(k, mode)
        score = approximate(f)
        cache[key] = score
        if leaders[mode] is None or score > leaders[mode][0]:
            leaders[mode] = (score, k)
        if score > contender_score:
            contender_score = score
            contender = f
        if score > best_score - 2e-13 and time.monotonic() < deadline-1.2:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        return score

    # Preserve the original mass, edge-scale, and gap cut families.
    cuts = set()
    count = int(params['cuts'])
    cumulative = np.cumsum(f0)
    for q in np.linspace(0.01, 0.99, count):
        if time.monotonic() >= coarse_end:
            break
        cuts.add(int(np.searchsorted(cumulative, q*cumulative[-1])))
    for d in np.geomspace(1, max(2, n//3), 18):
        if time.monotonic() >= coarse_end:
            break
        k = int(d)
        cuts.add(k)
        cuts.add(n-k)
    occupied = f0 > 0
    changes = np.flatnonzero(occupied[1:] != occupied[:-1]) + 1
    edges = np.r_[0, changes, n]
    widths = np.diff(edges)
    for j in np.argsort(widths)[::-1][:24]:
        if time.monotonic() >= coarse_end:
            break
        if not occupied[edges[j]]:
            cuts.add(int((edges[j]+edges[j+1])//2))
            cuts.add(int(edges[j]))
            cuts.add(int(edges[j+1]))
    cuts = sorted(k for k in cuts if 0 < k < n)
    # Space-filling order gives each coarse region a trial before nearby cuts.
    pending = list(cuts)
    ordered = []
    intervals = [(0, len(pending))]
    while intervals and time.monotonic() < coarse_end:
        next_intervals = []
        for lo, hi in intervals:
            if time.monotonic() >= coarse_end:
                break
            if lo < hi:
                mid = (lo+hi)//2
                ordered.append(pending[mid])
                if lo < mid:
                    next_intervals.append((lo, mid))
                if mid+1 < hi:
                    next_intervals.append((mid+1, hi))
        intervals = next_intervals
    modes = rng.permutation(3).tolist()
    for k in ordered:
        if time.monotonic() >= coarse_end:
            break
        for mode in modes:
            if time.monotonic() >= coarse_end:
                break
            inspect(k, mode)

    # Refine each mode's leader at shrinking grid scales, re-centering
    # after each successful move instead of spending all trials globally.
    step = max(1, n // max(8, count))
    while time.monotonic() < search_end:
        did_work = False
        ranking = sorted(range(3), key=lambda j: leaders[j][0] if leaders[j] else -np.inf, reverse=True)
        for mode in ranking:
            if time.monotonic() >= search_end:
                break
            if leaders[mode] is None:
                inspect(n//2, mode)
            if leaders[mode] is None:
                continue
            center = leaders[mode][1]
            for sign in (-1, 1):
                if time.monotonic() >= search_end:
                    break
                k = center + sign*step
                if 0 < k < n and (k, mode) not in cache:
                    inspect(k, mode)
                    did_work = True
        if step > 1:
            step = max(1, step//2)
        elif not did_work:
            break

    if contender is None or contender_score < baseline-float(params['repair_tolerance']):
        return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}
    if time.monotonic() >= deadline-1.5:
        return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}

    base = contender
    spec = fft.rfft(base, m)
    peak = fft.irfft(spec*spec, m)[:2*n-1].max()
    base = base / np.sqrt(peak)
    indices = np.flatnonzero(base > 0)
    starts = np.r_[True, (np.diff(indices) != 1) | (indices[1:]//256 != indices[:-1]//256)]
    labels = np.cumsum(starts, dtype=np.int64)-1
    groups = int(labels[-1])+1
    active = base[indices]
    beta = float(params['beta'])

    class Stop(Exception):
        pass

    def objective(x):
        nonlocal best_score, best_f
        if time.monotonic() >= deadline-1.5:
            raise Stop()
        f = np.zeros(n)
        f[indices] = active*np.square(x[labels])
        sp = fft.rfft(f, m)
        c = fft.irfft(sp*sp, m)[:2*n-1]
        peak = c.max()
        e = np.exp(beta*(c-peak))
        z = e.sum()
        smooth = peak + np.log(z)/beta
        num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
        total = f.sum()
        quick = num/(np.sum(np.abs(c))*np.max(np.abs(c)))
        if quick > best_score+1e-13 and time.monotonic() < deadline-1.2:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        g = 4*c
        g[1:] += c[:-1]
        g[:-1] += c[1:]
        g /= 3*num
        g -= e/(z*smooth)
        corr = fft.irfft(fft.rfft(g,m)*np.conj(sp),m)[:n]
        local = (2*corr[indices]-2/total)*active
        grad = 2*x*np.bincount(labels,weights=local,minlength=groups)
        value = np.log(num)-2*np.log(total)-np.log(smooth)
        return -value, -grad

    try:
        minimize(objective, np.ones(groups), jac=True, method='L-BFGS-B',
                 options={'maxcor': 7, 'maxiter': 10000, 'maxfun': 20000,
                          'ftol': 0.0, 'gtol': 0.0, 'maxls': 15})
    except Stop:
        pass
    if best_f is None:
        return init
    return {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}
"
